import 'package:audioplayers/audioplayers.dart';
import 'package:flutter/foundation.dart';

/// Every sound effect in the game. Files live in `assets/audio/` and are
/// generated by `tool/gen_audio.py`.
enum Sfx { click, dice, step, ladder, snake, win, six, blocked, turn }

extension SfxFile on Sfx {
  String get file => 'audio/$name.wav';
}

/// Plays effects and the music loop. Sound and music can be disabled
/// independently. Implementations must never throw into the UI.
abstract class AudioService {
  bool get soundEnabled;
  bool get musicEnabled;
  set soundEnabled(bool value);
  set musicEnabled(bool value);

  Future<void> play(Sfx sfx);

  /// Starts (or resumes) the background loop if music is enabled.
  Future<void> startMusic();
  Future<void> stopMusic();

  /// App went to the background / came back.
  Future<void> suspend();
  Future<void> resume();

  void dispose();
}

/// Real implementation on top of `audioplayers`. Players are created lazily
/// so tests and headless runs never touch platform channels.
class AudioPlayersService implements AudioService {
  AudioPlayersService({this.musicVolume = 0.35, this.sfxVolume = 0.9});

  final double musicVolume;
  final double sfxVolume;

  bool _sound = true;
  bool _music = true;
  bool _suspended = false;
  bool _broken = false;
  AudioPlayer? _musicPlayer;
  final List<AudioPlayer> _pool = [];
  int _next = 0;
  static const _poolSize = 4;

  @override
  bool get soundEnabled => _sound;

  @override
  bool get musicEnabled => _music;

  @override
  set soundEnabled(bool value) => _sound = value;

  @override
  set musicEnabled(bool value) {
    _music = value;
    if (!value) {
      stopMusic();
    } else if (!_suspended) {
      startMusic();
    }
  }

  AudioPlayer _sfxPlayer() {
    if (_pool.length < _poolSize) {
      final p = AudioPlayer()..setReleaseMode(ReleaseMode.stop);
      _pool.add(p);
      return p;
    }
    final p = _pool[_next];
    _next = (_next + 1) % _pool.length;
    return p;
  }

  @override
  Future<void> play(Sfx sfx) async {
    if (!_sound || _broken || _suspended) return;
    try {
      final p = _sfxPlayer();
      await p.stop();
      await p.play(AssetSource(sfx.file), volume: sfxVolume);
    } catch (e) {
      debugPrint('sfx failed ($sfx): $e');
      _broken = true;
    }
  }

  @override
  Future<void> startMusic() async {
    if (!_music || _broken || _suspended) return;
    try {
      final p = _musicPlayer ??= AudioPlayer()..setReleaseMode(ReleaseMode.loop);
      if (p.state == PlayerState.playing) return;
      if (p.state == PlayerState.paused) {
        await p.resume();
      } else {
        await p.play(AssetSource('audio/music.wav'), volume: musicVolume);
      }
    } catch (e) {
      debugPrint('music failed: $e');
      _broken = true;
    }
  }

  @override
  Future<void> stopMusic() async {
    try {
      await _musicPlayer?.pause();
    } catch (_) {}
  }

  @override
  Future<void> suspend() async {
    _suspended = true;
    await stopMusic();
  }

  @override
  Future<void> resume() async {
    _suspended = false;
    await startMusic();
  }

  @override
  void dispose() {
    _musicPlayer?.dispose();
    for (final p in _pool) {
      p.dispose();
    }
  }
}

/// No-op implementation that records what would have played (tests).
class SilentAudioService implements AudioService {
  final List<Sfx> played = [];
  int musicStarts = 0;
  int musicStops = 0;

  @override
  bool soundEnabled = true;

  @override
  bool musicEnabled = true;

  @override
  Future<void> play(Sfx sfx) async {
    if (soundEnabled) played.add(sfx);
  }

  @override
  Future<void> startMusic() async {
    if (musicEnabled) musicStarts++;
  }

  @override
  Future<void> stopMusic() async => musicStops++;

  @override
  Future<void> suspend() async => musicStops++;

  @override
  Future<void> resume() async => startMusic();

  @override
  void dispose() {}
}
